-- ═══════════════════════════════════════════════════════════
-- 0099_food_recettes_twix_gaufres_15_11.sql
-- STATUT : PROPOSITION — à exécuter puis confirmer par Renée-Lise
-- Auteur : Claude Code · Date de rédaction : 2026-11-15
-- Objet : 10 nouvelles fiches Bella'Food issues d'un second envoi
--   d'images le même jour (16 images, dont 8 doublons exacts de
--   fiches déjà ajoutées le 14/11 — Pain au beurre, Accras de morue,
--   Bûche de Noël, 6 recettes de dinde, Saumon en croûte feuilletée,
--   Crème dessert spéculoos (renvoyée 2x), Cinnamon rolls, Pintade
--   aux pommes, Danette au chocolat maison (version longue déjà en
--   base) — non repris ici pour éviter les doublons. La version
--   courte "Chez Nounou Alex" de la Danette, déjà explicitement
--   écartée le 14/11, est aussi ignorée.
--   Nouveau contenu réellement ajouté : Twix fait maison (recette
--   complète avec étapes), 3 pâtes à gaufres de l'infographie
--   "Savoir-Faire" (classique/croustillante/moelleuse, étapes
--   réelles), 5 variantes de goût de l'infographie "Gaufres maison"
--   (ingrédients seuls, sans étapes détaillées — signalé en notes),
--   et les Gaufres liégeoises (ingrédients seuls, sans étapes).
--   Catégorie "gaufre" créée (taxonomie food_recettes.categorie en
--   texte libre, pas de contrainte).
--   Non traité dans cette migration : la fiche tarifaire "Sydy
--   Nail's" (salon d'onglerie) présente dans le même envoi — hors
--   périmètre Bella'Food, nature à clarifier avec Renée-Lise.
--   Table food_recettes uniquement, pas de prix conseillé →
--   volontairement non synchronisé vers catalogue_produits.
-- Idempotent (WHERE NOT EXISTS sur nom + notes).
-- ═══════════════════════════════════════════════════════════

insert into public.food_recettes
  (nom, categorie, nb_parts, difficulte, temps_prepa, temps_cuisson, temps_repos, ingredients, etapes, notes, statut)
select v.nom, v.categorie, v.nb_parts, v.difficulte, v.temps_prepa, v.temps_cuisson, v.temps_repos, v.ingredients, v.etapes, v.notes, v.statut
from (values
('Twix fait maison', 'patisserie', 11, 2, 30, 20, 135, '[{"nom": "Farine", "quantite": 200, "unite": "g", "notes": "pour le sablé"}, {"nom": "Beurre doux", "quantite": 100, "unite": "g", "notes": "pour le sablé"}, {"nom": "Sucre glace", "quantite": 60, "unite": "g", "notes": "pour le sablé"}, {"nom": "Sel", "quantite": 1, "unite": "pincée", "notes": "pour le sablé"}, {"nom": "Sucre", "quantite": 150, "unite": "g", "notes": "pour le caramel"}, {"nom": "Beurre doux", "quantite": 80, "unite": "g", "notes": "pour le caramel"}, {"nom": "Crème liquide entière", "quantite": 100, "unite": "g", "notes": "pour le caramel"}, {"nom": "Fleur de sel", "quantite": 1, "unite": "pincée", "notes": "pour le caramel"}, {"nom": "Chocolat au lait", "quantite": 250, "unite": "g", "notes": "pour l''enrobage"}]'::jsonb, ARRAY['Préparer le sablé : mélangez la farine, le sucre glace et le sel. Ajoutez le beurre froid en morceaux et sablez du bout des doigts jusqu''à obtenir une texture sablée.','Cuire le sablé : tassez la pâte dans un moule rectangulaire (20x20 cm) recouvert de papier cuisson. Piquez le fond et enfournez à 180°C pendant 20 minutes. Laissez refroidir complètement.','Préparer le caramel : faites fondre le sucre à sec dans une casserole jusqu''à obtenir un caramel doré. Hors du feu, ajoutez le beurre puis la crème chaude (attention aux projections). Remettez sur feu doux 1 minute, ajoutez la fleur de sel et mélangez.','Verser le caramel : versez le caramel tiède sur le sablé refroidi. Lissez bien la surface et laissez prendre à température ambiante puis 1 heure au réfrigérateur.','Découper : une fois le caramel bien pris, démoulez et découpez des barres de la taille souhaitée (environ 2x8 cm). Placez-les au réfrigérateur pendant 30 minutes.','Enrober : faites fondre le chocolat au lait. Enrobez chaque barre à l''aide d''une fourchette. Déposez sur une grille et laissez figer au frais 15 à 20 minutes.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuce : laisser le caramel épaissir à température ambiante avant de le verser sur le sablé. Variantes : chocolat noir pour une version plus intense, vanille dans le caramel, sablé breton ou shortbread à la place du sablé classique. Conservation : boîte hermétique au réfrigérateur jusqu''à 1 semaine. Pour 10 à 12 barres.', 'actif'),
('Pâte à gaufres classique', 'gaufre', 4, 1, 10, 5, 30, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Sucre", "quantite": 40, "unite": "g"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Lait", "quantite": 30, "unite": "cl"}, {"nom": "Sucre vanillé", "quantite": 1, "unite": "sachet"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Mélangez la farine, la levure, le sucre, le sucre vanillé et le sel.','Ajoutez les œufs et mélangez progressivement.','Versez le lait petit à petit en fouettant pour obtenir une pâte lisse.','Ajoutez le beurre fondu et mélangez.','Laissez reposer la pâte pendant 30 minutes.','Faites chauffer le gaufrier et graissez-le légèrement.','Versez une petite louche de pâte et cuire pendant 3 à 5 minutes, jusqu''à ce que les gaufres soient bien dorées.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Pâte à gaufres croustillantes', 'gaufre', 4, 1, 10, 5, 30, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Beurre fondu", "quantite": 100, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Lait", "quantite": 20, "unite": "cl"}, {"nom": "Eau pétillante", "quantite": 10, "unite": "cl"}, {"nom": "Sucre vanillé", "quantite": 1, "unite": "sachet"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Mélangez la farine, la levure, le sucre, le sucre vanillé et le sel.','Ajoutez les œufs puis incorporez progressivement le lait.','Ajoutez le beurre fondu et mélangez jusqu''à obtenir une pâte homogène.','Incorporez délicatement l''eau pétillante.','Laissez reposer la pâte pendant 30 minutes.','Préchauffez et graissez légèrement le gaufrier.','Versez la pâte et cuisez jusqu''à obtenir des gaufres bien dorées et croustillantes.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Pâte à gaufres moelleuses', 'gaufre', 4, 2, 15, 5, 30, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Œufs", "quantite": 3, "unite": "piece"}, {"nom": "Sucre", "quantite": 60, "unite": "g"}, {"nom": "Beurre fondu", "quantite": 80, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Lait", "quantite": 25, "unite": "cl"}, {"nom": "Crème liquide", "quantite": 10, "unite": "cl"}, {"nom": "Sucre vanillé", "quantite": 1, "unite": "sachet"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Mélangez la farine, la levure, le sucre, le sucre vanillé et le sel.','Séparez les blancs des jaunes d''œufs.','Ajoutez les jaunes, le lait et la crème liquide au mélange.','Incorporez le beurre fondu et mélangez jusqu''à obtenir une pâte lisse.','Montez les blancs en neige puis incorporez-les délicatement à la pâte.','Laissez reposer la pâte pendant 30 minutes.','Faites chauffer le gaufrier, graissez-le légèrement et cuisez les gaufres jusqu''à ce qu''elles soient dorées et bien moelleuses.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Gaufres nature gourmande', 'gaufre', 4, 1, 10, 5, null, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Lait", "quantite": 40, "unite": "cl"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Méthode générale : mélangez les ingrédients secs, ajoutez les œufs puis le lait et le beurre fondu (et l''ingrédient signature de la variante), laissez reposer, puis faites cuire au gaufrier chaud et graissé jusqu''à coloration.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : méthode générale d''une pâte à gaufres (mélanger, reposer 30 min, cuire au gaufrier chaud et graissé jusqu''à coloration), à confirmer avec Renée-Lise pour le temps de cuisson exact. Issue de l''infographie "Gaufres maison — 5 versions irrésistibles".', 'actif'),
('Gaufres chocolat intense', 'gaufre', 4, 1, 10, 5, null, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Sucre", "quantite": 40, "unite": "g"}, {"nom": "Cacao en poudre", "quantite": 20, "unite": "g"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Lait", "quantite": 35, "unite": "cl"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}]'::jsonb, ARRAY['Méthode générale : mélangez les ingrédients secs, ajoutez les œufs puis le lait et le beurre fondu (et l''ingrédient signature de la variante), laissez reposer, puis faites cuire au gaufrier chaud et graissé jusqu''à coloration.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : méthode générale d''une pâte à gaufres (mélanger, reposer 30 min, cuire au gaufrier chaud et graissé jusqu''à coloration), à confirmer avec Renée-Lise pour le temps de cuisson exact. Issue de l''infographie "Gaufres maison — 5 versions irrésistibles".', 'actif'),
('Gaufres vanille gourmande', 'gaufre', 4, 1, 10, 5, null, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Lait", "quantite": 40, "unite": "cl"}, {"nom": "Extrait de vanille", "quantite": 2, "unite": "c. à café"}]'::jsonb, ARRAY['Méthode générale : mélangez les ingrédients secs, ajoutez les œufs puis le lait et le beurre fondu (et l''ingrédient signature de la variante), laissez reposer, puis faites cuire au gaufrier chaud et graissé jusqu''à coloration.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : méthode générale d''une pâte à gaufres (mélanger, reposer 30 min, cuire au gaufrier chaud et graissé jusqu''à coloration), à confirmer avec Renée-Lise pour le temps de cuisson exact. Issue de l''infographie "Gaufres maison — 5 versions irrésistibles".', 'actif'),
('Gaufres citron & pavot', 'gaufre', 4, 1, 10, 5, null, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Lait", "quantite": 40, "unite": "cl"}, {"nom": "Zeste de citron", "quantite": 1, "unite": "piece"}, {"nom": "Graines de pavot", "quantite": 1, "unite": "c. à soupe"}]'::jsonb, ARRAY['Méthode générale : mélangez les ingrédients secs, ajoutez les œufs puis le lait et le beurre fondu (et l''ingrédient signature de la variante), laissez reposer, puis faites cuire au gaufrier chaud et graissé jusqu''à coloration.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : méthode générale d''une pâte à gaufres (mélanger, reposer 30 min, cuire au gaufrier chaud et graissé jusqu''à coloration), à confirmer avec Renée-Lise pour le temps de cuisson exact. Issue de l''infographie "Gaufres maison — 5 versions irrésistibles".', 'actif'),
('Gaufres noisette croquante', 'gaufre', 4, 1, 10, 5, null, '[{"nom": "Farine", "quantite": 250, "unite": "g"}, {"nom": "Levure chimique", "quantite": 1, "unite": "sachet"}, {"nom": "Sucre", "quantite": 50, "unite": "g"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre fondu", "quantite": 50, "unite": "g"}, {"nom": "Lait", "quantite": 35, "unite": "cl"}, {"nom": "Poudre de noisettes", "quantite": 80, "unite": "g"}]'::jsonb, ARRAY['Méthode générale : mélangez les ingrédients secs, ajoutez les œufs puis le lait et le beurre fondu (et l''ingrédient signature de la variante), laissez reposer, puis faites cuire au gaufrier chaud et graissé jusqu''à coloration.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé. Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : méthode générale d''une pâte à gaufres (mélanger, reposer 30 min, cuire au gaufrier chaud et graissé jusqu''à coloration), à confirmer avec Renée-Lise pour le temps de cuisson exact. Issue de l''infographie "Gaufres maison — 5 versions irrésistibles".', 'actif'),
('Gaufres liégeoises', 'gaufre', 4, 2, 15, 5, 60, '[{"nom": "Farine", "quantite": 300, "unite": "g"}, {"nom": "Beurre mou", "quantite": 100, "unite": "g"}, {"nom": "Sucre", "quantite": 40, "unite": "g"}, {"nom": "Lait", "quantite": 120, "unite": "g"}, {"nom": "Levure sèche de boulanger", "quantite": 1, "unite": "sachet"}, {"nom": "Œuf", "quantite": 1, "unite": "piece"}, {"nom": "Sucre perlé", "quantite": 55, "unite": "g"}]'::jsonb, ARRAY['Étapes non détaillées sur la fiche source (liste d''ingrédients uniquement) : il s''agit d''une pâte levée (levure boulangère) dans laquelle on incorpore le sucre perlé en dernier, à laisser pousser avant cuisson au gaufrier — à confirmer avec Renée-Lise pour le temps de pousse et de cuisson exacts.']::text[], 'Fiche recette envoyée par Renée-Lise le 15/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif')
) as v(nom, categorie, nb_parts, difficulte, temps_prepa, temps_cuisson, temps_repos, ingredients, etapes, notes, statut)
where not exists (
  select 1 from public.food_recettes fr where fr.nom = v.nom and fr.notes = v.notes
);
